import clsx from 'clsx';
import './AcidSkeleton.css';

export interface AcidSkeletonProps {
    width?: string | number;
    height?: string | number;
    shape?: 'rectangle' | 'circle' | 'industrial';
    className?: string;
}

export const AcidSkeleton = ({
    width = '100%',
    height = '1rem',
    shape = 'rectangle',
    className
}: AcidSkeletonProps) => {
    const style = {
        width,
        height,
    };

    return (
        <div
            className={clsx('ac-skeleton', `ac-skeleton-${shape}`, className)}
            style={style}
        />
    );
};

.ac-skeleton {
    background: var(--ac-border-muted);
    position: relative;
    overflow: hidden;
    opacity: 0.8;
}

.ac-skeleton::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.1),
            transparent);
    animation: ac-skeleton-shimmer 2s infinite;
}

[data-theme='light'] .ac-skeleton::after {
    background: linear-gradient(90deg,
            transparent,
            rgba(0, 0, 0, 0.05),
            transparent);
}

.ac-skeleton-circle {
    border-radius: 50%;
}

.ac-skeleton-rectangle {
    border-radius: var(--ac-radius-sm);
}

.ac-skeleton-industrial {
    clip-path: polygon(5% 0, 100% 0, 100% 95%, 95% 100%, 0 100%, 0 5%);
}

@keyframes ac-skeleton-pulse {

    0%,
    100% {
        opacity: 1;
    }

    50% {
        opacity: 0.5;
    }
}

@keyframes ac-skeleton-shimmer {
    0% {
        transform: translateX(-100%);
    }

    100% {
        transform: translateX(100%);
    }
}
